namespace Aurora {
public sealed class RepairCommand {public string Title,File,Arguments;public bool Interactive;}
public static class RepairPlans {
    public static string Drive(string drive){if(!Regex.IsMatch(drive??"","^[A-Za-z]:$"))throw new ArgumentException("Invalid volume");return drive.ToUpperInvariant();}
    public static string Offline(string root){string path=Args.LocalPath(root);if(!Directory.Exists(Path.Combine(path,"Windows")))throw new ArgumentException(L.T("A pasta deve conter a instalação offline em Windows.","The folder must contain the offline Windows installation."));if(String.Equals(path.TrimEnd('\\'),Path.GetPathRoot(Environment.SystemDirectory).TrimEnd('\\'),StringComparison.OrdinalIgnoreCase))throw new ArgumentException(L.T("Esta é a instalação ativa. Use o modo online.","This is the active installation. Use online mode."));return path;}
    public static string Source(string path,string index){if(String.IsNullOrWhiteSpace(path))return "";string local=Args.LocalPath(path);if(File.Exists(local)){
        int n;if(!Int32.TryParse(index,out n)||n<1||n>999)throw new ArgumentException("Invalid image index");string ext=Path.GetExtension(local).ToLowerInvariant();if(ext!=".wim"&&ext!=".esd")throw new ArgumentException("Source must be WIM, ESD or a Windows source folder");return Args.Q("/Source:"+ext.Substring(1)+":"+local+":"+n);
    }if(!Directory.Exists(local))throw new DirectoryNotFoundException(local);return Args.Q("/Source:"+local);}
    public static RepairCommand Dism(string operation,string offline,string source,string index,bool limit){if(!new[]{"CheckHealth","ScanHealth","RestoreHealth","AnalyzeComponentStore","StartComponentCleanup"}.Contains(operation))throw new ArgumentException("Unsupported DISM operation");if(operation=="RestoreHealth"&&limit&&String.IsNullOrWhiteSpace(source))throw new ArgumentException(L.T("Informe uma fonte local de reparo para usar LimitAccess.","Provide a local repair source to use LimitAccess."));string target=String.IsNullOrWhiteSpace(offline)?"/Online":Args.Q("/Image:"+Offline(offline));string extra=operation=="RestoreHealth"?Source(source,index):"";return new RepairCommand{Title="DISM • "+operation,File="dism.exe",Arguments=target+" /Cleanup-Image /"+operation+(extra!=""?" "+extra:"")+(operation=="RestoreHealth"&&limit?" /LimitAccess":"")+" /NoRestart"};}
    public static string Present(RepairCommand command,CommandResult result,string description){
        // SFC uses exit 1 for an existing repair that needs a reboot. Preserve
        // the native code, without presenting that deferred operation as ERROR.
        if(command!=null&&result!=null&&Path.GetFileName(command.File??"").Equals("sfc.exe",StringComparison.OrdinalIgnoreCase)&&result.Code==1&&ResultTone.IsPendingRepair(result.Output)&&!ResultTone.IsFailure(result.Output))description=L.T("Pendente • Reinicialização necessária (1)","Pending • Restart required (1)")+Environment.NewLine+result.Output;
        string guidance=Guidance(command,result);return (guidance.Length==0?"":guidance+Environment.NewLine+Environment.NewLine)+description;
    }
    public static string Guidance(RepairCommand command,CommandResult result){
        if(command==null||result==null||!Path.GetFileName(command.File??"").Equals("dism.exe",StringComparison.OrdinalIgnoreCase))return "";
        if(result.Code==unchecked((int)0x800f081f))return L.T("Não foi possível concluir o reparo: o Windows não encontrou os arquivos necessários. Informe uma fonte compatível com a edição, arquitetura e versão do Windows.","Repair could not be completed: Windows did not find the required files. Provide a source matching the Windows edition, architecture and version.");
        if(result.Code==unchecked((int)0x800f0906))return L.T("Não foi possível baixar os arquivos de reparo. Confira a conexão e a origem configurada ou informe uma fonte local compatível.","Windows could not download repair files. Check connectivity and the configured source, or provide compatible local media.");
        if(result.Code==3017)return L.T("Não foi possível concluir a operação. O Windows solicita reinicialização para desfazer alterações antes de uma nova tentativa de reparo.","The operation could not be completed. Windows requires a restart to roll back changes before another repair attempt.");
        return "";
    }
}
public partial class MainWindow {
    bool repairRunning;
    void RunRepairs(RepairCommand[] commands,TextBox output){
        if(commands.Length==0||repairRunning||!RequireAdmin())return;
        if(!Confirm(T("Executar estas operações?\n\n","Run these operations?\n\n")+String.Join("\n",commands.Select(x=>x.Title+"\n"+x.File+" "+x.Arguments).ToArray())+T("\n\nNão interrompa o reparo. Faça backup dos arquivos importantes. Resultados completos serão guardados no histórico.","\n\nDo not interrupt repairs. Back up important files. Complete results will be saved in history.")))return;
        if(commands.Any(x=>x.Interactive)){if(commands.Length!=1)throw new InvalidOperationException("Interactive repair must run alone");RepairCommand cmd=commands[0];Process.Start(new ProcessStartInfo("cmd.exe","/d /k "+cmd.File+" "+cmd.Arguments){UseShellExecute=true,Verb="runas"});journal.Log(cmd.Title,"Opened interactive console: "+cmd.File+" "+cmd.Arguments);output.Text=T("Console interativo aberto. Responda ao CHKDSK e acompanhe o resultado nessa janela. O agendamento no próximo boot só ocorre se você confirmar na ferramenta.","Interactive console opened. Answer CHKDSK and monitor the result there. Scheduling at next boot occurs only if you confirm in that tool.");return;}
        repairRunning=true;output.Text=T("Operação em execução. Aguarde; reparos podem demorar bastante. O OuO não os encerra por tempo limite.","Operation running. Please wait; repairs can take a long time. OuO does not stop them on a timeout.");
        Work(T("Reparo do sistema","System repair"),()=>{StringBuilder result=new StringBuilder();foreach(RepairCommand cmd in commands){result.AppendLine(cmd.Title);try{CommandResult r=Runner.Run(cmd.File,cmd.Arguments,Int32.MaxValue);string message=RepairPlans.Present(cmd,r,Describe(r));journal.Log(cmd.Title,message);result.AppendLine(message);if(r.Code!=0&&r.Code!=3010&&r.Code!=1641)break;}catch(Exception e){result.AppendLine("ERROR: "+e.Message);break;}}return result.ToString();},r=>{repairRunning=false;output.Text=r;});
    }
